from pathlib import Path
from collections import Counter
import json,re

O=Path(__file__).resolve().parents[1]
B={b['id']:b for b in json.loads((O/'_source/blocks.json').read_text())}
edits=[]
def edit(i,title,problem,reason,benefit,text):
    bid=f'B{i:04d}';b=B[bid]
    assert (781<i<851 or 906<i<1128) and b['kind']=='p'
    assert b['style_name'].lower() not in ['caption','source code'] and not b['style_name'].startswith('heading')
    assert text!=b['text']
    assert re.findall(r'\[\d+\]',text)==re.findall(r'\[\d+\]',b['text']),(bid,'citations')
    nums=lambda t:Counter(re.findall(r'\d+(?:\.\d+)?',t))
    assert nums(text)==nums(b['text']),(bid,'numbers',nums(text)-nums(b['text']),nums(b['text'])-nums(text))
    heads=[x for x in B.values() if 781<=x['index']<=i and x['style_name'].startswith('heading')]
    edits.append({'block_id':bid,'title':title,'section':heads[-1]['text'],'old_text':b['text'],'new_text':text,'problem':problem,'reason':reason,'benefit':benefit})

edit(782,'章首：明确综合分析要回答的问题','章首列出了三类分析，但总体比较与对象分析之间的关系略显紧凑。','从前两章的研究分工转入组合效果，再说明总体指标如何引出恢复对象与漏检分析。','读者可以顺着比较目的理解本章，而不只是预先看到分析名称。','第三章研究训练文本改写后的监督保持，第四章研究预测组件修改后的关系依赖。本章在相同骨干、自由预测数量和原生完整对象评价条件下，比较四种训练与推理组合，分析两阶段合用时的效果，并通过完整关系对象对齐和漏检环节分析解释结果的变化。')
edit(784,'组合设置：按共同基线说明各配置的变化','四个缩写与训练、推理的变化集中出现，末句“共同参照”的作用较抽象。','保持四种配置定义，直接说明该设计用于分别估计哪几类差异。','配置名称、控制条件和待回答的问题对应得更清楚。','本章沿用第二章的官方测试划分、原生对象身份和严格评价规则，以包含BR-O的T0I0为完整基线，在相同测试文档和三个种子上比较四种组合。T1I0采用第三章的训练配置，并保留继承推理流程；T0I1保留基线训练配置，在对应I0终态上追加第四章的依赖闭合修正R_DC；T1I1同时采用新增训练配置与追加修正。通过这些组合，可以分别考察训练增量、追加推理增量及二者的交互。')
edit(785,'比较层次：区分整套配置与具体机制','“比较考察”“比较进一步分析”等结构重复，机制比较与组合比较的层次关系可更直接。','以固定条件为起点，分别交代整体配置和具体机制的解释范围。','整体增量不会被误读为某个损失项或动作的独立贡献。','表5-1列出各层次比较的解释范围。固定I0时，比较反映整套训练配置的作用；固定T1时，从相同I0终态出发，比较反映追加依赖闭合修正R_DC的条件增量。四种组合共同用于分析增益重叠与交互，成对目标、共同接受和集合动作等具体机制的贡献则由各自的受控比较判断。')
edit(788,'补充证据：说明历史记录、外部系统和CPU案例各自的用途','段落首句只区分两类比较，后文却同时引入历史记录、系统适配和CPU诊断。','按材料来源与用途展开，保留每类材料对应的评价条件。','读者能够理解这些材料为何分别解释，以及哪些可以与本章共同评价。','继承协议核查、外部系统比较和CPU诊断各有不同用途。补充表S2-1核查原MCR-BR协议下的继承配置，附录E转录其已公开结果，二者均不与本章严格评价数值混合汇总。附录G中的UniASA及Kawarada等的TextToText适配到相同骨干，采用共同评价器，同时保留各自的任务建模方式与公开接口，用于系统层面的比较。CPU诊断案例采用CPU-BIO-SGD在训练侧拟合后的测试预测及固定规则处理，用于说明可复核的错误变化。')
edit(791,'总体指标：由配置表现过渡到关系对象追踪','“判断完整配置是否保持……方向”较绕，表格与后续分析的分工不够直接。','先说明表中统计量，再点明总体指标与对象追踪分别回答什么。','总体表现和变化来源形成连续的分析步骤。','表5-2汇总四种配置在AAEC与CDCP上的组件F1和关系F1，其中“±”表示三个种子的样本标准差。下文先比较完整配置与各阶段单独使用时的总体表现，再按关系身份追踪变化来源。')
edit(794,'主要发现：先给出同骨干比较的结果','“在……上”“在……中”重复，末句的同骨干限定与结果稍有脱节。','将骨干条件放在句首，紧接均值排序及基线数值，再收束到完整配置效果。','主要发现更集中，同时保留固定骨干这一归因条件。','在Qwen3.5-9B固定骨干条件下，T1I1的组件F1和严格关系F1均值在两种语料上均高于其余三种配置。其关系F1分别为71.63和50.77，T0I0基线分别为65.69和41.79，反映了完整方法配置在这一条件下的效果。')
edit(796,'差值口径：解释表间舍入差异','“均值与差值分别……再……”包含多层计算关系，读者可能误以为先对展示值作差。','明确两张表均从未舍入结果出发计算，然后解释展示值相减的差异。','配对效应的来源更清楚，避免将舍入差异误作表格矛盾。','表5-3区分主要比较与探索性比较，列出平均配对差值、相应95%置信区间及三个种子的配对差值。表5-2的均值和表5-3的差值均从未舍入的逐种子结果计算，最后保留两位小数。因此，直接用展示均值相减，可能与所列配对差值相差0.01个百分点。下文以表5-3的配对差值为准。')
edit(799,'条件增量：将点估计、校正判断和探索性总增量分开','多个结果连续列报，整体增益的探索性身份出现在较生硬的“保持……身份”表述中。','保留全部数值与校正结论，用明确的比较类别收束总增量。','读者更容易分清正点估计、通过校正及探索性比较三个层次。','固定I0时，AAEC和CDCP的训练增量分别为2.56和3.30个百分点；固定T1时，追加修正增量分别为3.38和5.68个百分点。在14项主要比较的Holm校正后，CDCP训练增量及两种语料的追加推理增量达到统计显著性，AAEC训练增量未达到统计显著性。完整配置相对基线共提高5.94和8.98个百分点，该项为探索性比较。')
edit(804,'对象分析：点明恢复、误报与损失共同影响F1','开头罗列因素后，“解释组合表现”仍较宽泛。','把后续两个步骤与总体指标不能直接揭示的变化对应起来。','从总体分数转入对象分析的理由更清楚。','关系F1同时受到正确关系恢复、错误关系减少和原有正确关系丢失的影响，仅凭总体分数无法区分这些变化。本节先按相同关系身份比较两阶段恢复的对象，再从端点和关系选择两个层次分析仍未命中的金标关系。')
edit(806,'恢复对象：明确对齐单位和三种子汇总口径','对齐规则、对象类别和计数口径集中在长句中，“不同汇总方式”需要读者自行展开。','先交代参照和对齐标准，再解释成员分解与F1汇总的区别。','恢复关系的计数不会与逐种子指标均值混淆。','表5-4以T0I0正确识别的关系为基准，在每个种子内按完整关系的规范键，对齐两条单独路径和完整配置新增的TP。只有文档、完整源集合、目标和关系标签均一致，才视为同一对象。在此基础上，区分两阶段共同恢复、各自独有以及仅在组合后恢复的关系。表中计数为三个种子的合计，用于分解对象来源；逐种子F1均值则采用另一种汇总方式。')
edit(809,'成员恒等式：解释完整配置中的恢复与损失','“新增TP的交集”和“丢失单路恢复”的对应关系较压缩，末句偏记录性表达。','保留所有集合类别与恒等式，以完整配置如何同时计入收益和损失收束。','表中各列可以顺着定义核对到最终TP。','“共同恢复”是T1I0与T0I1相对T0I0新增TP的交集，“训练独有”和“修正独有”分别是两者的差集，“组合独有”指仅在T1I1中新增的TP。完整配置也可能丢失单路恢复的关系或初始TP。各项满足“初始TP＋共同恢复＋训练独有＋修正独有＋组合独有−丢失单路恢复−丢失初始TP＝完整TP”，据此核对恢复、损失与终态计数。')
edit(811,'正确关系损失：将计数落到总体指标的解释','“丢失单路恢复”连续用作名词短语，句子略显账目化。','补足关系这一对象，随后直接说明总体提高与局部损失可以并存。','读者更容易理解表中损失项的实际含义。','组合结果同时包含恢复与损失。AAEC丢失了单路恢复的关系1条、初始TP 41条；CDCP对应为0条和7条。因此，总体F1提高仍可能伴随部分正确关系丢失。')
edit(813,'漏检分类：围绕关系成立所需的端点条件解释','“能够在最终图中同时成立”和“组件条件”略显抽象。','直接说明正确端点是否同时存在，再定义端点齐全时的选择漏检。','两类漏检的区别更具体，也便于读者理解它们为何需要分别统计。','完整关系的恢复要求正确端点同时存在于最终图中。表5-5a将未命中的金标关系分为“端点缺失”和“端点齐全但未选”两类：前者缺少关系成立所需的组件，后者已有全部正确端点，却仍未选中相应关系。分别统计这两类漏检，可以判断总体改善是否伴随各类漏检的同步减少。')
edit(817,'首个阻断：说明分类顺序与互斥计数','“定位首个阻断”先于操作定义，读者可能将其理解成独立因果判断。','先说明按表列顺序检查与一次归类，再解释该方法避免重复累计的用途。','诊断标签的产生方式更清楚，为后文的解释边界作好铺垫。','表5-5b按表列顺序检查完整配置中的未命中关系，将每条关系归入首个阻断环节，且只归类一次。该方法区分终态端点、完整候选槽位、评分和决策环节，避免同一漏检被重复累计。')
edit(821,'诊断边界：具体区分候选存在与端点恢复','“不同条件”较概括，候选与终态的差异可以由动作直接说明。','先说明候选入池为何不足，再将按序定位与因果检验分开。','读者不易把候选覆盖当成最终恢复，也不会由诊断计数直接推出机制因果。','候选端点进入池中，并不意味着正确端点最终被选中；相近或竞争跨度的存在，也不能视为金标关系的完整端点已经恢复。上述首个阻断是按既定顺序定位的诊断环节，与端点—选择分解共同描述漏检分布，不构成对各环节影响的独立因果检验。')
edit(823,'多源分析动机：解释部分恢复与整条命中的区别','从多源定义到长源集合困难的转折较快，“部分端点恢复”与严格计数的关系可更紧密。','先说明完整匹配要求，再解释总体指标为何可能掩盖长源集合困难。','分组分析有明确的评价依据，后接样本分布更自然。','CDCP的一条关系可以包含多个源组件，只有完整源集合、目标和标签均匹配时才计为TP。随着源成员增多，即使恢复了部分端点，整条关系仍可能未被命中；总体F1因此可能掩盖长源集合的恢复困难。原生测试集共252条关系，包括218条单源、20条双源、6条三源和8条四源及以上关系，其中多源关系为34条。')
edit(824,'分组统计：明确计数合计与指标均值的分工','分号连接两种统计口径，结尾“单一F1替代所列均值”略绕。','将计数与指标各自的汇总方法分句说明，再给出不能互换的结论。','读者可以直接判断表格每列的统计单位。','表5-6按完整源成员数报告四种配置的表现。TP、FP和FN为三个种子的计数合计，关系F1及其标准差由逐种子指标汇总。因此，用合计计数重新计算的单一F1不能替代所列均值。')
edit(827,'分组结果：把F1提升与误报减少联系起来','“组内F1提高也可能……”与单源组观察衔接略松。','保留单源计数变化，并直接提醒多源指标也受到误报变化影响。','指标提高不会被等同于新增完整关系数量。','CDCP单源组从T0I0到T1I1，TP由309增加至349，FP由494减少至342。多源组同样需要结合正确恢复和误报变化解释结果：关系按完整源集合匹配，组内F1提高也可能来自误报减少，不能将F1增量直接换算为新增完整关系的数量。')
edit(829,'多源限制：按表达、恢复和选择三个环节检查','“评价单位保持一致”“分别检查”较抽象，三个检查对象之间的顺序可更清楚。','保留完整对象评价规则，并将表达覆盖、端点恢复和关系选择组织为连续检查。','读者能定位限制来自接口还是预测决策，避免以拆边改变评价对象。','各配置和外部系统均以完整源集合为评价单位，不能将长源关系拆成多条独立边来增加TP。附录G单列外部方法转换四源及以上对象时的表达损失。结合分组结果，应依次检查接口能否表达完整对象、正确端点是否恢复以及关系是否被选中，以定位多源关系的限制。')
edit(831,'跨骨干设置：先交代共享部分，再说明独立配置','模型用途、共同条件、独立模块和解释限制压在长段中，共享增强的含义不够突出。','按模型分工、共同输入、独立模块和比较边界排列信息。','更容易理解该实验检验的是共享增强下的迁移，而非所有模块同时缩放。','Qwen3.5-9B承担主实验、完整消融和错误分析；Qwen3.5-4B用于考察同系列较小骨干，Qwen2.5-7B-Instruct用于衔接已有生成式基线。三者使用相同的原生划分、种子和自由预测数量协议，并共享由9B生成和审核的增强视图；抽取生成器G、对象评分器S、源组提案器P、OOF校准及开发策略则分别配置。因此，该实验检验的是共享增强条件下的方法迁移。4B仍依赖较强模型提供的增强数据，跨版本差异也不能解释为纯参数规模效应。')
edit(834,'跨骨干结果：将基线水平和方法增量分开表达','“具有较高的基线和最终均值”与后面的增量数字集中在一个长句中。','先交代同表中的基线和完整配置水平，再逐一报告增量并保留因果边界。','模型自身水平与方法带来的变化不易混为一谈。','表5-7同时列出各骨干的基线和完整配置结果。Qwen3.5-9B在两种语料上的基线与最终均值均较高，其完整配置相对同骨干基线的关系F1增量为5.94和8.98个百分点；4B的增量为6.64和10.61个百分点，Qwen2.5-7B-Instruct为6.88和11.56个百分点。本实验中，较高基线对应较小增量，但尚不能据此确定参数规模与增益的因果关系。')
edit(837,'补充检验：说明独立校正及结论范围','比较族构成、抽样索引和校正身份连续出现，主、补充比较的关系可更直接。','保留比较总数及抽样规则，将补充结果和主比较不变的事实分别表述。','读者可以同时看清统计支持和它所对应的实验范围。','补充比较族由2种骨干、2种语料和3项比较组成，共12项，复用主实验的2000次文档与种子重采样索引，并单独进行Holm校正。表5-8中的增量均为正，校正后均达到统计显著性；9B主实验14项比较的校正结果不受影响。这些结论限于两个语料、三个种子的共享增强设置，不能外推为所有模型或领域均有相同增益。')
edit(839,'章末小结：按总体结果、对象变化和剩余困难收束','小结包含多种层次，统计结果与对象互补之间的递进可以更明确。','先回收阶段条件增量，再说明恢复差异及损失，最后概括诊断与迁移范围。','章节结论形成连续解释，同时保留未显著和未确认协同的关键限制。','本章从总体指标、完整关系对象和漏检分布三个层面分析两阶段的组合效果。两阶段条件增量的点估计均为正，但AAEC训练增量未通过主要比较族的Holm校正。两条单独路径恢复的关系部分不同，完整配置也会丢失部分原有正确关系，交互区间尚不足以确认稳定协同。当前漏检主要归入终态端点缺失和评分未过门，CDCP长源集合的恢复仍然困难。跨骨干结果为共享增强条件下的方法适用性提供了补充证据，具体机制的贡献仍由相应受控比较判断。')

edit(843,'全文总结：围绕共同依赖问题概括两项工作','训练与推理流程较完整，但总结段需要更突出两项工作共同处理的问题。','以组件变化和关系依赖为主线，压紧步骤列举，保留两侧的关键机制及评价连接。','总结更像对全文工作的归纳，读者不必再次逐项重建方法流程。','本文围绕端到端论辩挖掘中的组件与关系依赖，研究训练文本改写后的监督保持，以及预测图修改后的结构修正。训练侧通过关系影响域、标注输运和因素掩码识别可保留的监督，在原文完整图生成目标之外引入可靠因素学习与成对约束。推理侧从继承I0终态出发，在固定候选和对象评分下，将组件变化与受影响关系的重建作为同一事务，依据分项效用、编辑预算和返回规则作出决策。两项工作以原生对象身份和严格评价衔接，第五章从整体分数、恢复对象及剩余错误分析其组合关系。')
edit(844,'结论中的数值：突出总体增量和阶段检验的层次','总增量、条件增量与校正结论密集列报，“经……校正”后的对象需读者回看。','保留代表性数值，以两种固定条件明确阶段比较，并让校正结论紧跟其后。','独立阅读结论时仍能识别整体表现、条件效果和未显著项。','在AAEC和CDCP上，Qwen3.5-9B完整配置的严格关系F1分别为71.63和50.77，相对同骨干ICIC/MCR-BR基线提高5.94和8.98个百分点。分阶段看，固定I0的训练增量分别为2.56和3.30个百分点，固定T1的追加修正增量分别为3.38和5.68个百分点。14项主要比较经Holm校正后，CDCP训练增量及两种语料的追加推理增量达到统计显著性，AAEC训练增量未达到统计显著性。跨骨干实验支持方法在所测试模型间、共享增强条件下的迁移，具体配置见附录K。')
edit(845,'机制总结：将受控比较与系统收益的归属对应起来','开头“由对应受控比较判断”略像规则提示，后文各项发现与归属结论可直接相接。','从受控比较的实际结果起笔，再说明不能把整体收益全部归于单一机制。','机制结论更有依据，也保留CPU案例仅补充过程分析的用途。','受控比较中，成对项在CDCP上的增量通过主要比较族的Holm校正，在AAEC上未通过；共同接受、集合动作及等预算重生成的比较仍不足以支持跨语料的稳定优势。因此，系统总体增益不能全部归于单个损失项或动作。CPU参考事务与独立规则案例补充了过程分析，并保留了失败情形。')
edit(847,'适用限制：把效用失配、计算成本和回退分别说清','“有……条……记录”的量词链较长，成本与评分限制的关系略显拥挤。','简化统计单位的表达，先说效用与真实指标的差别，再交代成本和弱评分回退。','风险有明确的观察单位和触发条件，后续校准方向也更有针对性。','固定效用上升不保证严格F1上升。主配置中，按文档与种子组合统计，AAEC有14/240条、CDCP有3/450条记录的严格关系F1下降；额外评分和搜索也带来了计算成本。弱评分版本v0未满足开发集原TP保留要求，因而触发回退。扩大动作空间之前，需要先检验决策区域的评分质量，以及修改对原有正确关系的影响。')
edit(848,'局限归纳：将样本规模、审核分层和补充语料分别对应到结论','三种限制并列，部分限定使用“总体较低……不能保证……”的长结构。','按估计精度、监督可靠性和跨域证据三类问题解释，各自保留适用范围。','读者能知道每项限制具体影响哪个判断。','本实验仅使用三个种子，CDCP长源关系的样本也较少，限制了细粒度比较的估计精度。增强池各审核层的不安全率及区间存在差异，因此总体不安全接受率较低，并不意味着每一层都满足同等可靠性要求。CasiMedicos转换文件有69条记录缺少正文，ArgUNSC没有独立官方测试划分；二者仅用于核对文本与原生标注结构，不用于推断跨语言、医学判断或跨域泛化效果。')
edit(850,'后续研究：让每个方向直接回应当前限制','“围绕三个限制展开”的总起较概括，方向与检验方式可更紧密。','按长源集合、效用失配和计算开销依次提出改进对象与验证要求，保留跨域及动作范围的决策条件。','展望从当前证据中的具体困难出发，避免成为泛泛的性能提升目标。','后续研究可从当前限制出发推进。长源集合漏检需要改进完整源组提案，并增加相应独立测试样本；效用与严格F1不一致，需要进一步考察决策区域的代价敏感校准；额外推理开销则要求比较低成本对象评分与集合动作的质量收益和资源消耗。共享增强设置下的效果能否保持，还应在新增领域语料上检验。是否扩大集合动作范围，应由独立的质量与成本比较决定。')

edit(908,'坐标记录：先定义转换规则，再报告异常分布','坐标定义、残差处理和各划分计数挤在一起，“其中……个不……”读起来较费力。','先说明三层坐标和边界保留规则，再明确不与整词对齐的组件数量。','规则与审计结果分开，读者更容易核对特殊跨度如何保留。','原始字符坐标采用半开区间[start,end)，Python字符串按Unicode码点切片。评价token由固定正则分词得到，模型子词保留offset mapping；词内边界另存字符残差，往返转换不得隐式扩展边界。原生AAEC／CDCP共含10,986个组件。不与整词边界完全对齐的组件中，AAEC训练集有3个、测试集有2个，CDCP训练集有19个、测试集有0个；全部24个均保留原字符身份。坐标和关系引用审计未发现越界或悬空端点。')
edit(912,'运行关联：说明连接键、检查点与执行状态各自的作用','“以……连接”缺少记录主体，检查点命名和运行状态的关系较压缩。','明确通过哪些字段关联记录，再按基础权重、检查点和来源摘要说明。','读者可沿记录字段追踪结果，同时不会以名称代替实际状态。','主结果通过dataset／document／seed／method字段关联预测、候选、评分、事务和成本记录。主实验各模块统一使用Qwen/Qwen3.5-9B基础权重，固定revision见附录J；抽取检查点按rt-q35-9b-语料-方法-s种子-e5命名，OOF、S评分头和P提案头使用独立前缀。原始上传及划分摘要保存在相应manifest中，检查点名称不作为执行状态的依据。')
edit(914,'补充语料：将使用内容和评价范围写清','“使用提供的转换文件的……”修饰链较长，数据保留与模型成功解析的区别可更自然。','先说明沿用转换文件哪些字段，再交代缺失记录和划分状态。','原生材料的核对用途更明确，补充语料不易被误读为主效果评价。','CasiMedicos和ArgUNSC沿用所提供转换文件中的正文、类型、标签与split，不添加不存在的官方划分。CasiMedicos的69条空正文记录原样保留，不计为模型成功解析；ArgUNSC的144条记录均为unsplit_author_release。补充案例仅分析标注结构，主效果评价仍基于AAEC与CDCP。')
edit(918,'校准说明：明确参数选择和共享的层级','“开发κ”“其语料、种子和对象族”等压缩表达使参数归属不够直观。','把开发阶段的选择动作和文档内参数共享分别说明。','同一文档使用哪一组校准参数更容易理解。','组件头与关系头分别校准，q=sigmoid(a·logit(rawq)+b)。κ在开发阶段按上述固定顺序选择，不依据测试结果调整；同一文档内属于同一对象族的对象，共用该语料、种子和对象族对应的校准参数。')
edit(922,'登记顺序：用完整句说明事件时钟和追加分析','首句省略谓语，“敏感性明确置于……”略像记录字段注释。','补足登记主体，按时间原点、事件顺序和材料绑定组织说明。','登记材料更容易阅读，追加敏感性分析的地位仍清楚保留。','登记标识为RT-PREREG-01，版本为rt-v1.0-frozen。以D0为计时原点，依次记录配置冻结、训练、OOF与校准、策略选择、测试评价及追加敏感性分析。敏感性分析安排在主要比较之后，不追加为主要假设；各事件绑定同一登记JSON与文件摘要。')
edit(931,'序列化身份：分清显示编号与规范键','“字符片段逐字等于”“关系键进一步含”等语句较机械。','用核对和构成动作说明原文片段、组件键及完整关系键的对应。','序列化例子与表中原文的联系更清楚，身份保留条件不变。','字符片段与表3-1逐字一致。显示编号可以变化，但组件规范键始终由文档、字符跨度和类型确定；关系键还包含规范排序的完整源集合、目标和标签。转换仅进行显式大小写映射与坐标输运，不补回缺失端点。AAEC stance保留为属性，不据此补造supports／attacks边。')
edit(934,'快照与阶段记录：明确文件连接的对象','“以同一……连接”及多次“登记”堆叠，快照和阶段文件的作用不够分明。','先列快照内容，再说明阶段文件如何关联图状态，最后给出来源和状态索引。','读者可按用途查找快照、阶段图及模块记录。','追加修正快照保存I0终态G0、完整候选V/P、固定q及未校准分数、κ、种子和语料身份。inherited_stages_v9.jsonl按文档、种子和训练配置关联Grank、Gpre及BR-O返回的G0。继承图与追加事务的来源和执行状态见附录J的S2.3与S2.6；模型、分词器、OOF、校准及状态另行登记。')
edit(936,'事务轨迹：按记录内容、编辑计数和提交检查展开','多个账本和检查要求连续压缩，“对全部提交逐次求和”不够自然。','分别说明记录包含什么、两种编辑量如何计算，以及拒绝时哪些内容保留。','轨迹复核可沿清楚的顺序进行，语义编辑与计算消耗不易混淆。','追加事务至少记录步骤、组件新增／删除、关系新增／删除、提交前后分项效用、评分版本和停止原因。终态净变化相对I0终态G0计算，局部累计编辑逐次累加追加阶段的全部提交，BR-O编辑另行登记。每次提交后检查关系端点是否存在，以及跨度兼容、标签互斥和CDCP完整源连续性是否满足。拒绝事务时保留当前图，但已发生的计算成本仍计入。')
edit(938,'回退说明：区分全局超时、局部失败和资源记账','多种返回条件由分号串联，读者需要自行判断各规则属于哪条路径。','先交代共同起点和预算，再分别说明全局与局部的返回条件。','失败发生后保留哪个状态、资源如何记录更容易查到。','追加修正从I0终态G0开始计数：全局路径净编辑≤24／96，局部路径累计编辑≤24／96，均不包含BR-O已有编辑。局部每轮最多32次尝试、3次接受，最多4轮；提交已评估合格的项不再消耗尝试额度。全局路径超时且有incumbent时，复核全部接受门与约束；无有效改进则返回G0。局部路径拒绝事务时保留当前图，提交失败时回滚到提交前的完整合法图，中断时返回最近的完整状态；尚无追加提交时即返回G0。继承与追加阶段已消耗的时间、模型调用和token均不因回退而扣除。')
edit(945,'故障验收：说明通过所指的判定','输入输出保存与故障判定挤在一句中，“预期返回”略压缩。','先说明记录内容，再单独解释故障注入通过的含义。','不会将预期的失败返回误读成系统从未发生故障。','表B-1各检查项的输入、输出身份与配置共同保存，坐标、原生计数及CPU事务另有可执行参考复算记录。故障注入中的“通过”表示返回结果符合预期，并不表示未发生故障。')
edit(947,'最优证书：将检查分支与主参考实现分开','接口覆盖与参考实现能力连续出现，最优目标和唯一输出的区别容易被略过。','按接口检查、正常输入表现、未执行步骤和统计范围组织。','读者可以区分已检查分支与主参考实现实际给出的保证。','接口检查覆盖候选溢出、超时、有／无可行解、提交失败、中断恢复、缺分和破同分的全部返回分支。主参考求解在正常输入上没有超时，最优目标gap为0。该参考实现不执行三级词典序破同分，因此只声明目标值最优，不声明多解时具有唯一语义输出。正常输入与故障挑战记录分别汇总，时限比例也分别统计。')
edit(949,'案例记录：说明保留内容与案例选择方式','“组件跨度类型”“实际CPU规则”等连续名词使记录说明略显拥挤。','补足字段间关系，并将规则输入、事后选例和原生标注的范围分句说明。','读者更容易区分实际预测案例和仅展示标注结构的案例。','案例保留语料、文档ID、split、全文SHA-256、原文、组件跨度与类型、完整关系、预测前后集合及TP/FP/FN。实际CPU规则仅使用训练侧类型签名和预测跨度距离。案例为事后选取，用于解释行为，原始输出和失败情形均保留；原生标注案例不附加模型行为。')
edit(951,'固定评分证明：说明抵消的是共同对象的权重','“共同对象抵消”省略了权重这一实际计算对象，“隐藏代价”略抽象。','点明权重抵消，并把规范键变化和依赖关系差集相连。','公式性质和对象身份的关系更准确直观。','固定对象权重aX(o)=2qX(o)−κX时，两个图中共同对象的权重相互抵消，效用差因此严格等于新增权重之和减去删除权重之和。类型或边界变化会产生新键，全部依赖关系都须纳入差集，不能因沿用显示ID而遗漏相应代价。')
edit(953,'构造例解释：明确名义插入为何仍属于集合动作','“实际形态仍是”之前同时列两种提议，操作与分类依据可以更清晰。','按删除失败、冲突闭合和实际动作形态解释，保留构造例的证明范围。','单对象邻域不可达的原因更易理解，且不会误作真实F1证据。','单独删除任一旧组件时，效用增量为−0.30，无法通过严格改进门。若插入b或仅声明替换一个旧组件，冲突闭合仍要求删除另一个旧组件，实际操作因而是2→1，不属于单对象邻域。该构造只说明集合动作的可达性，不证明真实F1改善。')
edit(954,'终止性质：连接固定效用、状态不再访与有限终止','“有限候选形成有限状态空间”之后推理较短，末句两个单调性并置略生硬。','将严格改进如何排除再访讲清，再集中交代前提变化和真实指标限制。','性质的前提、推论及适用边界可连续读懂。','有限候选对应有限状态空间。若每次接受都使同一固定效用严格增加，就不可能再次访问已有状态，接受序列因此有限终止；实际预算可以使运行更早停止。缺分、动态重评分或改变κ会破坏该命题的前提，须重新定义运行身份。真实F1还取决于未知TP与预测总量，固定效用单调上升并不保证F1单调上升。')
edit(957,'成果归属：把继承基础、实现工具和本文工作分层说明','“深化可靠监督对应及修改后的完整依赖决策”名词密集，具体工作对象不够直接。','保留已有工作和工具归属，用动词明确本文研究的两类问题。','贡献说明更具体，组合分析也不会被抬高为独立算法创新。','本文继承MCR-BR[34]的专项适配、线索提示、多候选整图重排序及有界修改，使用LoRA、MLP、JS散度和整数规划作为实现工具。在此基础上，研究如何保持可靠的监督对应，以及如何对修改后的完整依赖作出决策。两阶段组合比较用于区分条件增量与交互，不作为独立算法创新。')
edit(959,'配套材料：明确逐文档计数的所属系统','“主模型及外部适配逐文档计数”修饰归属紧凑，材料列表与定位规则衔接较快。','补足主模型和外部适配系统的关系，随后说明表格生成及案例定位。','配套材料的内容和查找用途更明确。','配套材料包括规范化语料、共同配置、主模型与外部适配系统的逐文档计数，以及候选、评分、事务、审核、成本和共同抽样索引。表3-6、表4-6和表5-3已从完整联合计数重新生成。引用原文保留原拼写，案例通过全文SHA-256、字符区间和原生身份定位；记录类型与复算入口见附录J。')
edit(964,'弱评分回退：补足失败条件和诊断用途','“不满足开发TP保留”省略要求，“强制输出仅用于表”未直接说明其诊断位置。','明确未满足开发要求导致实际返回初始图，再说明强制输出和主版本的关系。','实际策略输出与用于分析的强制输出更易区分。','v0的初始关系F1为39.81。所有测试过的κ与校准条件均未满足开发TP保留要求，因此部署时返回初始图，强制输出仅用于表4-18的分析。该记录与主实验v1不共享检查点或候选快照，v0→v1的差值不能解释为单一阈值消融。')
edit(968,'开发选择：按风险过滤、指标选择和破同分说明','“全部合格”“保持相同限制”重复，选择步骤与统计口径交织。','先报告各阈值能否通过，再按操作顺序解释选择，最后集中说明开发与测试汇总差异。','参数如何选定及F1按什么单位汇总都更便于核对。','表D-1中，CDCP的κR=1在所有δ条件下均未满足5%的原TP损失限制，κR=0.5则均合格；AAEC的κR=1也均合格。选择时统一执行5%限制，在合格条件中最大化汇总关系F1，再按4.3.1节的平局规则选取δ=0.20。开发F1由三个种子的计数汇总后计算，主测试分数则为逐种子F1均值。此处原TP以相应I0终态G0为参照，比较须使用相同开发文档、种子和预测身份。')
edit(970,'CPU训练配置：明确负采样和测试覆盖','参数、采样和预测以省略主语的短句相接，负例排序后的保留方式略压缩。','保留全部超参数，补足采样动作和官方测试文档的对应顺序。','CPU诊断流程可以直接按训练、采样、预测顺序理解。','CPU-BIO-SGD采用SGD log_loss组件模型(alpha=10⁻⁵，12轮)和关系模型(alpha=10⁻⁴，20轮)，种子为17、29、43。关系负采样保留可表达正例，并按哈希排序保留max(20,8×正例数)个负例。模型对两种语料官方80／150篇测试文档全部预测，不进行超参数搜索。')
edit(971,'CPU后处理：把规则输入与测试标注用途分开','删除规则、最近目标、金标用途及历史协议说明由长句连续承载。','按后处理规则、语料差异和标签可见性说明，保留非历史盲测的事实。','规则实际如何决策更清楚，测试标注被用于审计的事实也不被弱化。','后处理依据训练集中出现过的源类型集合—目标类型—关系标签签名，删除不受支持的预测组合。AAEC进一步为每个预测源保留中点距离最近的目标；CDCP不拆分联合源，也不添加新边。规则决策不读取测试金标，金标仅用于计数。实际CPU协议同时保留此前已读取测试标注进行语料审计的事实，因此不将该流程称为历史盲测。')
edit(973,'案例范围：区分预测诊断、原生标注和构造输入','几种材料性质并列，最后一句“现实案例”与前句原生标注的联系稍显笼统。','明确CPU输出独立解释，再分别交代文档、语料和构造材料的用途。','不同材料支持什么结论更易查阅，成功和失败案例均得到保留。','实际CPU输出用于错误剖析，与主模型数值分开解释。essay098保留成功和失败两个种子，CDCP、CasiMedicos及ArgUNSC则展示原生标注。形式证明和接口挑战使用的构造输入不属于现实案例，不能替代原始数据内容。')

edit(975,'历史结果存档：明确转录材料与当前实验的区别','“逐表保留……协议映射表除外”的例外后置，材料用途可更早说明。','将例外置于开头，再说明转录身份及沿用的统计协议。','读者进入各表前即可知道数值来源和解释条件。','除协议映射表外，本附录逐表转录MCR-BR[34]已公开的数值与方法名称。这些记录不代表本文独立复现，也不属于新增方法的实验结果。表中“±”的统计定义、数据划分和评价方式均沿用原文，不能直接按本文的新协议解释。')
edit(987,'原版消融：补足原消融对象与当前机制的对应','“专项适配、线索、多候选及有效性消融”是压缩列举，与当前机制的区别略显突兀。','明确这些是原版消融所考察的对象，再说明不能替代当前比较。','历史消融与本研究机制的关系更容易识别。','本表对应ICIC公开版Table 2[34]，考察专项适配、线索、多候选及有效性的消融。它们不能替代本文对完整影响域、成对学习和事务闭合的消融比较。')
edit(991,'验证器一致性：区分一致率与正确性校准','两种指标的否定判断连在一起，所对应的验证对象可进一步点明。','先说明原二元验证器的一致性，再保留自比较与金标准确性的区别。','一致性结果不会被误用来证明完整对象评分正确。','本表对应ICIC公开版Table 3[34]。原二元验证器的一致性结果不能替代完整对象评分器的正确性校准；与自身比较所得的一致率，也不能说明对金标的预测准确性。')
edit(999,'修正行为归属：明确原版动作属于哪个阶段','“不能移作”偏材料管理用语，动作归属与比例解释可以更自然。','直接说明动作所属阶段及统计不能转用的原因。','继承动作和本文追加动作的行为证据不易混淆。','本表对应ICIC公开版Table 6[34]。Replace及Promote/Demote属于BR-O，其统计不能作为BR-C或BR-J的行为分布；动作占比也不等于真实错误分布。')
edit(1007,'历史迁移评价：按指标与使用范围解释','“历史表”“独立于”等表达略像备注，历史协议的实际指标应先明确。','先交代有向无标签指标和粗粒度标签，再限定该记录的统计用途。','历史跨域成绩与当前严格原生评价更容易区分。','本表对应ICIC公开版Table 4[34]，采用有向无标签Link-F1和粗粒度标签，与本文严格原生关系评价分开解释。该表仅保留已发表记录，不参与当前主表、显著性比较或模型升级增幅计算。')
edit(1010,'符号索引：说明名称如何避免跨章混用','“使用完整名称”“分开命名”“对应符号”连续出现，查阅目的略被重复说明稀释。','保留各类命名规则，以跨章首次定义和评价量区别为主线。','读者更容易知道何时查符号、何时按完整对象名称理解。','表F-1汇总方法中的对象及其局部作用域。各章公式沿用既有符号，首次定义和跨章节叙述则使用“输入文档”“改写集合”“变化对象集合”“关系候选池”等完整名称。评价量写作Precision和Recall，以区别于图对象集合；完整对象计数、概率评分、累计编辑和终态净变化也分别使用各自符号，避免跨层混用。')
edit(1014,'坐标接口：沿替换、重分词和映射核验展开','操作步骤、索引排除和失败处理集中在长段中，执行先后可更清楚。','按实际处理顺序组织，并把索引位移与被排除位置的关系写明。','实现者更容易追踪位置如何更新，也能区分报错与拒绝变体的条件。','标注输运先按原字符区间替换指定槽位，回填全文后重新分词，更新全部组件位置，并分别保存字符坐标、评价token和模型子词之间的映射。构造第三章的组件子词集合 Bxc 时，依据原文字符跨度和分词器offset mapping定位输入子词，排除聊天模板及连续提示位置，并补偿由此产生的索引位移；句子头采用相同规则。训练表示映射不一致时报错；增强槽位重叠或坐标往返不一致时拒绝相应变体，保留问题金标。')
edit(1015,'训练接口：将标签可见性、梯度核验和分支更新分开','辅助输入、反传判定和门控规则连续堆叠，单个零梯度的解释与整体连接检查不够突出。','按输入边界、受控反传、综合连接判定及训练/推理阶段划分说明。','读者可分别核对标签是否泄漏、梯度路径是否有效以及各分支由什么目标更新。','训练辅助头只读取回答开始前的输入表示，endxh 取全文输入结束处的隐藏状态，不取金标回答末尾。金标跨度仅用于定位监督，待预测的组件类型和关系标签不作为辅助头输入。梯度核验对具有非零对齐损失的受控输入单独反传，检查共享生成参数的计算图连接与梯度范数、基础权重是否冻结、隐藏状态是否保持连接，以及输入是否包含金标回答。连接判定综合计算图、参数更新资格和数值梯度，单个零梯度不自动说明断路。输入阶段关闭结论专项门控，对齐项不直接训练该分支，专项分支由生成损失更新。开发评价和测试时移除辅助头，推理评分器另按第四章定义。')
edit(1016,'推理接口：让章节索引按功能排列','多个节号和接口名由分号串联，执行规则、对照定义和Oracle范围易混读。','按事务、队列预算、顺序对照、Oracle和接口索引依次说明。','读者能依据具体问题快速找到对应规则，保留覆盖统计与Oracle成绩的区别。','从I0终态G0开始，追加修正R_DC的冲突闭合与关系依赖域遵循4.4节。队列使用状态键、六类轮转和独立批长，预算、提交及回退遵循4.5.1节。顺序对照的两个提交阶段见4.6.1，外层计数与阶段账本见附录B.3。若报告Oracle，须按4.6.2节固定候选与约束，离线优化金标匹配目标；本文仅报告覆盖，没有新增Oracle成绩。模块接口为SelectRegion、BuildCandidates、EnumerateQueue、ScoreObject、EvaluateTransaction、Commit和EvaluateCounts，输入输出及错误身份见附录A、B。')
edit(1022,'外部系统：解释同骨干适配的比较身份','“端到端适配对照”“承担机制定位”等压缩表达使对照用途略抽象。','直接说明保留什么、统一什么以及其他文献的用途。','外部系统结果不会被误读为原论文分数的直接搬用。','外部端到端对照采用UniASA[48]和Kawarada等的TextToText[7]。本文保留其结构与训练目标，将两者适配到Qwen3.5-9B，使用相同的官方测试划分和严格原生评价器；这些结果并非直接移植原论文公开分数。QOS式适配仅作为第三章数据构造的近邻方法，其余文献用于说明相关机制的位置。')
edit(1024,'格式转换：说明预测对象如何进入严格评价','多条格式规则以分号相连，“收缩后的FP和完整FN”的含义较密集。','分别说明AAEC属性处理和CDCP源集合限制，再解释长源收缩的计数结果。','表达限制与评分错误不易混淆，也保留不补金标端点的条件。','AAEC预测的stance保留为属性，不据此生成新的普通关系；字符跨度和组件类型按预测本身转换，无法解析的端点不查金标补回。CDCP统一使用规范排序的sources数组，当前外部适配接口最多表达3个源成员。更长源集合若发生收缩，按收缩后的预测对象计FP，完整金标计FN，不将其展开为二元TP。')
edit(1028,'外部比较范围：将系统差异与单一机制效应分开','“三种子共同评价”与“不把系统差异解释为……”紧接，控制条件的用途可更清楚。','先明确共同种子评价和系统自身差异，再交代保存记录及探索性身份。','同骨干系统比较的意义和归因限制更容易同时把握。','外部系统保留各自结构与训练目标，在三个种子上共同评价，因此系统差异不能解释为本文某个损失项的因果效应。预测图、整数TP/FP/FN及格式转换后的源集合均予保存。外部检验保持探索性，不在读取结果后并入14项主要比较族。')
edit(1034,'外部结果解释：由观察转入差异来源','“尤其不能……”从一般系统差异跳到长源接口，衔接略紧。','先陈述均值观察，再以CDCP接口为具体限制，最后回到机制判断的证据来源。','总体系统比较和内部机制比较各自回答什么更明确。','两种语料上，完整系统的严格关系F1均值均高于两个外部适配对照。尽管骨干相同，各系统的训练目标、任务建模和原生表示接口仍有差异。例如，CDCP长源集合的表达损失不能归为评分器错误。单一机制的贡献仍须依据第三、四章的内部受控比较判断。')
edit(1037,'成本记录：区分主实验、补充运行与共享增强','运行数量、增强复用和表格范围集中在一段，主补充范围切换较快。','先列两类运行，再说明共享材料及各自成本登记位置。','读者更容易判断表中的成本覆盖哪些运行，GPU小时口径保持明确。','9B主实验登记54个最终训练、36个OOF、12个评分头和6个提案头；4B与2.5-7B补充实验的四种配置另登记24个最终训练、72个OOF、24个评分头和12个提案头。增强与审核仅进行一次，各骨干复用相同视图和掩码。表H-1汇总9B主实验，补充运行见backbone_registry_v9.json；GPU小时为两卡墙钟小时之和。')
edit(1045,'域外审核：说明发现变化后为何不增加监督','样本归属、语境效应和审核一致性接得较紧，“独立裁决参照”较抽象。','从抽样范围出发说明监督限制，再交代审核者一致性与模型决定的不同评价对象。','域外发现的意义更具体，人工一致率不会代替模型接受质量。','域外样本不属于四层J_A，不并入表3-8的Nh。域外变化表明，局部端点影响域无法覆盖全部语境效应，因此默认不为这些未经完整核查的变体关系新增监督。审核者一致性只评价标注过程，模型接受质量仍以独立裁决为参照。')
edit(1049,'路由阈值：把运行观察与硬件适用条件相连','“固定小池全局、大池局部的资源选择”较压缩，“重新做探测”不够正式。','明确变量规模、求解路径和迁移设备后的重新测量要求。','阈值的经验依据更清楚，也保留了硬件和候选约束的适用范围。','2500变量时，两种语料P95均在时限内；3000及4000变量时出现超时，支持小池全局、大池局部的固定路由。阈值依赖当前硬件与候选约束，更换设备须重新进行训练侧探测。')
edit(1057,'复算入口：按脚本职责说明材料使用方式','材料列表后连续使用“对应”，脚本间的分工较像字段备注。','保留脚本原名及处理对象，以完整句连接复算顺序和各脚本用途。','使用配套材料时更容易选对入口，主与补充记录的范围清楚。','主实验与跨骨干实验均保存逐文档整数计数、候选、评分、事务、成本及共同抽样索引，复算顺序见“修订说明与复算入口.txt”。主脚本处理9B记录，cross_backbones_v9.py处理两种补充骨干组合实验，stage_records_v9.py处理继承与追加阶段记录。')

edit(1062,'补充数据审计：明确原始记录、缺失记录和可用数量','多个划分计数省略量词，“可用分别……”较难与前面的划分逐一对应。','补足数量所指的记录，并将缺失保留与上游issues分开说明。','各划分数量可直接对应，同时不将历史问题误记为本次发现。','CasiMedicos原始数据共622条：train的434条中有53条缺正文，validation的63条中有8条缺正文，test的125条中有8条缺正文，可用记录依次为381、55、117条。69条空正文记录均无组件与关系，其ID继续保留。上游issues共341项，不将其改记为本次新发现的坐标错误。ArgUNSC保留144条记录和36项上游issues，不生成新的官方测试划分。')
edit(1066,'原文定位：说明案例核验方式和来源','案例名连续列出，“统一文件含”略像清单注释。','按原文核验、预测案例、标注案例和定位字段组织。','读者能快速找到英文片段的核验方式及各案例性质。','英文引文通过text[start:end]核验。essay077的主条件事务与essay098的两条实际CPU诊断分别保存；CDCP 00662保留完整双源集合，CasiMedicos和ArgUNSC仅展示原生标注。统一记录文件包含全文哈希、字符坐标及原生对象，用于定位这些案例。')
edit(1069,'公共配置导读：说明本附录的整理范围','“统一……配置、数据用途……”动作对象较宽泛，主版本与其他协议的关系可更直接。','以汇总内容开头，再给出主版本和历史、补充记录的位置。','读者进入统计附录前即可明确当前配置与其他记录的层次。','本附录汇总Qwen3.5-9B主实验的配置、数据用途、统计输入、模块身份和执行范围，主版本为RT-V9-Q35-9B-FREE。历史协议记录保留在S2.1及附录E中，跨骨干补充配置见5.5节与附录K。')
edit(1073,'历史协议核查：解释为何不并入当前比较族','“历史核查列”“重新列报”等词偏报表说明，旧新协议的差异可更自然呈现。','先说明该表与公开记录的对应，再说明当前基线使用的新配置。','历史核查的参考作用和当前统计边界更明确。','本表保留Qwen2.5原协议的历史核查结果，与附录E的已发表记录对应。当前T0I0已按Qwen3.5-9B共同配置和自由数量协议重新报告，因此本表的旧协议值不并入14项主要比较族。')
edit(1075,'划分与去重：按读取、训练侧处理和测试保留说明','多个文档编号嵌在长句中，去重仅发生在训练侧这一条件不够醒目。','保留全部编号，分开说明语料读取规则与训练侧去重动作。','具体排除对象和所有测试文档保留的边界便于核对。','AAEC按发布的train-test-split.csv匹配ID，CDCP按原压缩包的train/test目录读取。全文哈希去重仅在训练侧进行：AAEC的essay171／210／400保留essay171，essay209／377保留essay209；CDCP保留00410，排除正文重复且标注不完整的00411。训练集与测试集不存在全文哈希交叉重复，全部测试文档均保留。')
edit(1076,'坐标处理：区分显示文本、空白修整和词内边界','三种处理规则连续压缩，最后“通过字符残差往返”略不完整。','依次说明两种语料的实际处理，再补足三层坐标的转换动作。','读者不易把空白规范化理解为任意扩展字符边界。','AAEC测试标注中的11个显示文本差异均来自尾部制表符，坐标仍有效。CDCP保留原坐标，并规范组件首尾空白，训练集和测试集分别修整3166、810次。字符严格评价保留24个无法精确对齐整词的组件，不将其边界扩展到相邻词；三层坐标利用字符残差完成往返转换。')
edit(1077,'OOF分组：明确源文档及增强视图共同持出','“按源文档及全部增强视图分组”“每个持出源”较压缩。','直接说明源文档与其视图共同分组，并保留运行数和候选产生条件。','读者更容易理解持出单位及候选生成器的信息边界。','三折OOF将每个源文档及其全部增强视图共同分组。T0与T1、两种语料和三个训练种子共对应36个OOF运行条目。每个持出源的候选仅由未见该源的生成器产生；拟合、校准与策略用途及其规模见正文2.5节。')
edit(1084,'基础模型配置：按版本、输入和模板参数说明','模型版本、架构、软件和关闭功能集中在长句中，模板参数与软指令的区别可更清楚。','保留固定版本和全部开关，分别说明文本路径与thinking控制方式。','配置可直接复核，关闭thinking不会被误解为普通聊天指令。','基础权重与分词器固定为Qwen/Qwen3.5-9B@21eca8a083a2121a92fba681f4a7c72cf20ff1a7，架构类为Qwen3_5ForConditionalGeneration，使用Transformers 5.8.0。实验仅输入文本，不启用视觉、MTP推测解码或长上下文扩展。通过聊天模板参数enable_thinking=false关闭thinking，不以/think或/nothink软切换代替；共享视图组保持相同摘要。')
edit(1085,'配置与执行状态：按登记文件职责解释','两个登记文件的职责与版本要求集中列出，“把……分开登记”略口语。','分别点明模块注册、执行状态和版本核对的用途。','配置存在与参考计算已执行不会被混为同一事实。','module_registry_v9.json固定各模块的基础模型、可训练参数、输入输出、训练用途和缓存键。execution_status_v9.json分别登记“配置”与“CPU参考计算已执行”的状态。图表、统计和案例统一引用同一版本；材料目录提供逐文件SHA-256，用于核对各项记录对应的文件。')
edit(1091,'统计计数：明确主键、恒等式和失败文档处理','字段定义、行数、宽表来源和失败规则密集排列，数据约束不易逐项查阅。','按记录身份、整数约束、原始来源和失败口径组织说明。','读者能顺着复算输入检查一致性，零失败也仍限定于本版正常主输入。','statistical_counts_v9.csv以dataset、document_id、seed、method、object_family为主键，source_group记录源全文哈希，共含30,360行。TP、FP和FN均为非负整数，同一文档及对象族的TP+FN在各方法间保持一致。原始宽表保留training_counts、solver_counts及external_counts，重复的I0条目已核对一致。按失败文档协议，空预测仍保留原金标分母；本版正常主输入的失败数为0。')
edit(1092,'联合重采样：把输入材料和每次抽样动作分开','“包含……种子……NumPy……”是一长串不同性质的条目。','先列固定输入和随机数设置，再说明共享索引的抽样与输出。','统计复算的材料、操作和结果能逐一对应。','复算包包含14项主要比较清单primary_family_v9.json，以及两语料各2000次bootstrap_indices；固定训练种子为17／29／43，随机数生成器为NumPy PCG64，抽样种子为72026／72027。每次按源文档与训练种子交叉抽取，全部方法共享索引，并保存逐种子效应、95%区间、原始p和Holm p。脚本与输入摘要固定后，可重复生成统计结果。')
edit(1093,'主补充统计：明确复算用途与独立校正','主记录用途与跨骨干比较身份接续较快，“分别保存”指代较宽。','先交代主实验输入用于什么，再说明补充比较复用什么和单独处理什么。','共同抽样索引不再容易被误读为同一个比较族。','主实验复算材料包括自由预测数量下的预测图、冻结评分和整数计数，用于联合重采样及CPU事务重放；辅助记录、模型注册表和阶段成本分别保存。跨骨干实验复用相同文档与抽样索引，但12项补充比较单独校正，不并入主实验14项比较。脚本入口及逐文件摘要见配套说明。')
edit(1095,'模型选型依据：区分官方能力与本任务证据','榜单数值、选型结论和实验条件连续出现，采用榜单的用途可以更明确。','保留官方比较数字，以选型参考连接到任务分数不能外推的限制。','读者能理解选型理由，而不会将通用榜单优势当作本任务增益。','模型选择参考官方同表能力及本文的实验分工[51][53][54]。9B与4B的IFEval分别为91.5和89.8，LongBench v2分别为55.2和50.0，为优先考虑9B提供参考，但不预测AAEC/CDCP增益。本文关闭thinking，采用较短的固定上下文，未复现官方榜单条件，因此不将榜单百分差换算为任务F1。三模型均采用Apache-2.0许可，架构与来源见附录K。')
edit(1098,'模块共享：说明哪些参数共享、哪些独立训练','“S/P可共享”“A/V固定”“阶段驻留”等术语连续出现，跨骨干条件容易被略过。','依次解释主条件共享方式、跨骨干固定部分和硬件加载方式。','模块层面的比较范围更清楚，不能被误读为整体参数规模同步变化。','文本与聊天模板绑定同一模型revision。9B主条件下，S/P可共享冻结文本编码，但头参数与G分离，A/V也不加载G的LoRA。跨骨干实验固定A/V为9B，各骨干分别训练G/S/P，因此不属于所有模块同步缩放。两张A100按阶段加载并驻留所需模块，避免同时加载多份完整基础权重。')
edit(1102,'历史数量协议：按恒等式、构造方式和解释范围展开','“初始预测构造为……”较生硬，等式和历史构造之间的原因关系可更直接。','保留计数恒等式，明确受控候选如何保持对象数，再限定可作出的判断。','FP与FN相等的来源更容易理解，同时保持构造记录与自然解码的区别。','对任意去重后的预测集合P和金标集合G，|P|=TP+FP、|G|=TP+FN，因而FP−FN=|P|−|G|。v6构造初始预测时，为每个金标对象保留一个候选，通过改变类型或标签制造错误，同时保持对象总数，因此12行I0关系计数均满足FP=FN。该等式来自受控数量设计，单凭等式不能判断测试标签是否泄漏，该构造也不代表模型自然解码结果。')
edit(1108,'版本比较：对应历史记录、当前主结果和补充骨干','“分别报告……以区分……”与前文各版本切换稍显拥挤。','按当前同骨干、补充骨干、历史审计的顺序说明，再归纳比较原则。','不同版本的数据用途更容易识别，骨干变化和方法增量不易混算。','v9主结果与外部适配对照均采用9B同骨干自由预测数量协议，4B与Qwen2.5-7B-Instruct的四种配置另行保存。v6受控数量表仅用于历史协议审计。每个骨干均分别报告基线和完整配置，用于区分骨干变化与方法增量；历史公开结果和当前同协议适配结果也分别解释。')
edit(1109,'材料版本与运行状态：明确文件摘要能核对什么','多种清单并列，文件摘要和执行记录的作用可更直接。','先说明来源与执行范围不同，再分别给出模块、执行、统计及版本核对入口。','读者可以核对材料版本，同时不会以哈希完整性代替运行证据。','语料处理、模型配置和CPU参考计算各有不同的来源与执行范围。配置清单标识模块，execution_status_v9.json登记记录来源及执行范围，统计清单关联输入与输出。文件SHA-256用于核对材料版本，模型实际运行情况则须结合相应执行记录判断。')
edit(1112,'官方能力表：说明指标与本任务的联系及差异','几项榜单与任务的对应较密集，“不同预算”与不推导任务分数的关系可更顺畅。','先列可参考的能力维度，再说明榜单未评价的对象和实验条件差异。','选型依据具体可读，同时保留不从榜单差值推算论辩结果的边界。','表K-1摘录官方同表语言任务结果，仅作为选型参考[51][53]。IFEval、IFBench和MultiChallenge涉及格式与复杂指令遵循，LongBench v2涉及较长输入理解，但均未评价原生论辩组件的边界、类型及完整源组。官方模型默认使用thinking，本文采用非thinking结构化输出，预算也不同，因此不按榜单差值推导AAEC/CDCP数字。')
edit(1115,'历史模型定位：保留反例并解释接口衔接用途','“新协议四种配置结果和旧公开值互不替换”压缩较多，历史模型作用可更清楚。','先保留非全面占优的观察，再说明未参与同表的模型如何用于本文。','模型选择不会被写成单一规模排序，历史与当前结果的关系更明确。','9B并非在所有任务上均优于4B，例如同表中的TAU2-Bench略低。Qwen2.5-7B未出现在该同条件比较表中，因此本文不拼接不同榜单计算相对增益。2.5模型卡强调结构化输出能力，本文使用它衔接历史方法接口；新协议下四种配置的结果与附录E中的旧公开值分别保留，不相互替代。')
edit(1117,'架构说明：明确层数、隐藏维与名义规模的含义','模型简称与数字密集出现，“对应模型命名”较省略。','补足各模型架构的谓语，保留文本任务与视觉参数的边界。','架构差别更容易查阅，固定revision的用途也更明确。','3.5-9B和4B均采用32层文本网络，包括8个门控全注意力块和24个线性注意力块，隐藏维分别为4096、2560。2.5-7B采用传统GQA文本网络，共28层，隐藏维为3584。3.5的名义规模按模型名称表述，附带视觉参数不参与本文文本任务。三个版本均固定官方revision，不仅记录可能变化的main分支。')
edit(1120,'适配参数：解释相同rank为何不代表相同预算','“同rank不等于同可训练参数量”之前的挂载范围较压缩，后面的控制条件与差异可衔接得更自然。','由注意力块挂载范围解释参数差别，再明确比较对象与保持一致的条件。','读者能区分训练步骤预算和实际可训练参数量。','两种3.5骨干仅在8个全注意力块的q/k/v/o上挂载LoRA，2.5则在28个注意力块上使用相同语义接口。因此，相同rank并不意味着可训练参数量相同，2.5的LoRA总量可以高于9B。本文据此报告配置迁移效果，不声称参数预算完全相同；训练epoch、有效源批量、视图身份和追加编辑预算保持一致。')
edit(1123,'跨骨干接口：分开头维度、坐标映射和上下文预算','三类技术设置连续列报，子词索引不能共享的原因和上下文限制混在一起。','先说明独立头与校准记录，再说明分词差异，最后集中交代上下文预算。','每项限制都有对应对象，模型上限不会被误读为本实验实际输入长度。','S的组件／关系输入维度为2d和3d+87，P的完整源组输入为3d+7；各骨干独立保存头、OOF检查点、Platt系数及策略记录。不同模型分别分词，跨骨干评价通过规范字符坐标对齐，不共用子词索引。9B/4B的原生上下文上限为262144，2.5配置默认为32768，更长上下文需额外扩展；本文输入预算为4096，不启用这些扩展，长上下文榜单仅作为选型参考。')
edit(1127,'开发策略与补充材料：说明选择的先后条件','“依次要求……最大”将过滤、最优化和破同分写成并列要求。','按风险过滤、合格项择优及平局处理的顺序说明，保留计数材料规模。','策略选择可以按步骤理解，补充材料仍能直接对应复算入口。','开发策略仅在训练侧策略划分上选择：先要求原TP损失不超过5%，再选择汇总关系F1最大的合格项，平局时优先取较大的κ和δ。补充材料包含5520行组合实验计数、5520个预测图、2760份冻结候选池及求解记录，并复用主实验的统计抽样索引。模块配置和执行状态说明见附录J的S2.3与S2.6。')

